import queue
import threading
from typing import Callable, Any


class QueueWorker:
    def __init__(self, callback: Callable[[Any], None]):
        self.queue = queue.Queue()
        self.callback = callback
        self.running = False
        self.thread = None

    def _worker(self):
        while self.running:
            try:
                item = self.queue.get(timeout=0.5)
            except queue.Empty:
                continue

            try:
                self.callback(item)
            except Exception as e:
                print(f"Error processing item: {e}")
            finally:
                self.queue.task_done()

    def start(self):
        self.running = True
        self.thread = threading.Thread(target=self._worker, daemon=True)
        self.thread.start()

    def stop(self):
        self.running = False
        if self.thread:
            self.thread.join(timeout=5)

    def put(self, item: Any):
        self.queue.put(item)

    def join(self):
        self.queue.join()


if __name__ == "__main__":
    def process_item(item):
        print(f"Processing: {item}")

    worker = QueueWorker(process_item)
    worker.start()

    for i in range(5):
        worker.put(i)

    worker.join()
    worker.stop()
